draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
var padL = W * 0.19, padR = W * 0.17, padT = 30, padB = 22;
var cw = (W - padL - padR) / 3;
var rh = (H - padT - padB) / 4;
var sym = [
  ["u", "c", "t"],
  ["d", "s", "b"],
  ["e", "mu", "tau"],
  ["nu e", "nu mu", "nu tau"]
];
var chg = ["+2/3", "-1/3", "-1", "0"];
var i, j, x, y;

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
for (j = 0; j < 3; j++) {
  ctx.fillText("generation " + (j + 1), padL + cw * (j + 0.5), padT - 12);
}

for (i = 0; i < 4; i++) {
  for (j = 0; j < 3; j++) {
    x = padL + cw * j;
    y = padT + rh * i;
    ctx.fillStyle = i < 2 ? C.faint : C.paper;
    ctx.fillRect(x + 3, y + 3, cw - 6, rh - 6);
    ctx.strokeStyle = C.rule;
    ctx.lineWidth = 1;
    ctx.strokeRect(x + 3, y + 3, cw - 6, rh - 6);
    ctx.fillStyle = i < 2 ? C.accent : C.figure;
    ctx.font = "14px ui-sans-serif, system-ui, sans-serif";
    ctx.fillText(sym[i][j], x + cw / 2, y + rh / 2);
  }
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
for (i = 0; i < 4; i++) {
  ctx.fillText("charge " + chg[i], padL + cw * 3 + 8, padT + rh * (i + 0.5));
}

ctx.textAlign = "right";
ctx.fillStyle = C.accent;
ctx.fillText("quarks", padL - 8, padT + rh);
ctx.fillStyle = C.figure;
ctx.fillText("leptons", padL - 8, padT + rh * 3);

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("6 quarks + 6 leptons = 12 fundamental fermions", W / 2, H - padB / 2);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
var names = ["proton", "neutron", "lambda-0", "omega-minus", "pi-plus", "K-minus"];
var content = [
  ["u", "u", "d"],
  ["u", "d", "d"],
  ["u", "d", "s"],
  ["s", "s", "s"],
  ["u", "anti-d"],
  ["s", "anti-u"]
];
var qc = { u: 2 / 3, d: -1 / 3, s: -1 / 3 };
var lab = { u: "+2/3", d: "-1/3", s: "-1/3" };
var k = Math.round(p.which);
if (k < 0) k = 0;
if (k > 5) k = 5;
var qs = content[k];
var n = qs.length;

var Q = 0, B = 0, S = 0, i;
for (i = 0; i < n; i++) {
  var s0 = qs[i];
  var anti = s0.indexOf("anti-") === 0;
  var f = anti ? s0.substring(5) : s0;
  var sign = anti ? -1 : 1;
  Q += sign * qc[f];
  B += sign / 3;
  if (f === "s") S += sign * -1;
}

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.font = "14px ui-sans-serif, system-ui, sans-serif";
ctx.fillText(names[k], W / 2, 22);

var r = Math.min(34, W / 12);
var gap = r * 2.9;
var cx0 = W / 2 - gap * (n - 1) / 2;
var cy = H * 0.5;
ctx.font = "13px ui-sans-serif, system-ui, sans-serif";
for (i = 0; i < n; i++) {
  var cx = cx0 + gap * i;
  var s1 = qs[i];
  var anti1 = s1.indexOf("anti-") === 0;
  var f1 = anti1 ? s1.substring(5) : s1;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = anti1 ? C.paper : C.faint;
  ctx.fill();
  ctx.strokeStyle = anti1 ? C.figure : C.accent;
  ctx.lineWidth = 2;
  if (anti1) ctx.setLineDash([4, 4]);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText(s1, cx, cy - 8);
  var qv = (anti1 ? -1 : 1) * qc[f1];
  ctx.fillStyle = C.figure;
  ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
  ctx.fillText((qv > 0 ? "+" : "") + (Math.abs(qv - 2 / 3) < 1e-6 ? "2/3" : Math.abs(qv + 2 / 3) < 1e-6 ? "-2/3" : qv > 0 ? "1/3" : "-1/3"), cx, cy + 12);
  ctx.font = "13px ui-sans-serif, system-ui, sans-serif";
  if (i < n - 1) {
    ctx.fillStyle = C.rule;
    ctx.fillText("+", cx + gap / 2, cy);
  }
}

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(W * 0.12, cy + r + 22);
ctx.lineTo(W * 0.88, cy + r + 22);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var line = "charge " + (Q > 0 ? "+" : "") + Math.round(Q) + "e    baryon number " + Math.round(B) + "    strangeness " + Math.round(S);
ctx.fillText(line, W / 2, cy + r + 40);
ctx.fillStyle = C.figure;
ctx.fillText(n === 3 ? "three quarks: this is a baryon" : "quark plus antiquark: this is a meson", W / 2, cy + r + 60);

out.note = names[k] + ": Q = " + (Q > 0 ? "+" : "") + Math.round(Q) + "e, B = " + Math.round(B) + ", S = " + Math.round(S);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
var M = p.M, m1 = p.m1, m2 = p.m2;
var ok = M > m1 + m2;
var pc = 0, E1 = 0, E2 = 0, b1 = 0, b2 = 0;
if (ok) {
  var A = M * M - (m1 + m2) * (m1 + m2);
  var Bb = M * M - (m1 - m2) * (m1 - m2);
  pc = Math.sqrt(A * Bb) / (2 * M);
  E1 = Math.sqrt(pc * pc + m1 * m1);
  E2 = Math.sqrt(pc * pc + m2 * m2);
  b1 = pc / E1;
  b2 = pc / E2;
}

var cy = H * 0.52;
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(W * 0.06, cy);
ctx.lineTo(W * 0.94, cy);
ctx.stroke();

ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("parent at rest, momentum zero", W / 2, 18);

var period = 3.2;
var ph = t % period;
var reach = W * 0.40;

if (!ok) {
  ctx.fillStyle = C.figure;
  ctx.fillText("forbidden: parent lighter than the two daughters", W / 2, cy - 24);
  ctx.beginPath();
  ctx.arc(W / 2, cy, 12, 0, Math.PI * 2);
  ctx.fillStyle = C.faint;
  ctx.fill();
  ctx.strokeStyle = C.rule;
  ctx.stroke();
  out.note = "M = " + M.toFixed(1) + " MeV is below m1 + m2 = " + (m1 + m2).toFixed(1) + " MeV, so there is no decay";
} else if (ph < 0.9) {
  ctx.beginPath();
  ctx.arc(W / 2, cy, 14, 0, Math.PI * 2);
  ctx.fillStyle = C.accent;
  ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.fillText("M", W / 2, cy);
} else {
  var u = (ph - 0.9) / (period - 0.9);
  var bmax = Math.max(b1, b2, 1e-6);
  var d1 = reach * u * (b1 / bmax);
  var d2 = reach * u * (b2 / bmax);
  var x1 = W / 2 - d1, x2 = W / 2 + d2;

  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W / 2, cy);
  ctx.lineTo(x1, cy);
  ctx.moveTo(W / 2, cy);
  ctx.lineTo(x2, cy);
  ctx.stroke();

  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.arc(x1, cy, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = C.figure;
  ctx.beginPath();
  ctx.arc(x2, cy, 10, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = C.ink;
  ctx.fillText("m1 = " + m1.toFixed(1), x1, cy - 24);
  ctx.fillText("m2 = " + m2.toFixed(1), x2, cy - 24);
  ctx.fillText("p = " + pc.toFixed(1) + " MeV/c", x1, cy + 26);
  ctx.fillText("p = " + pc.toFixed(1) + " MeV/c", x2, cy + 26);
}

ctx.textAlign = "left";
ctx.fillStyle = C.figure;
ctx.fillText("equal and opposite momenta, always", W * 0.06, H - 14);

if (ok) {
  out.note = "p = " + pc.toFixed(1) + " MeV/c, E1 = " + E1.toFixed(1) + " MeV, E2 = " + E2.toFixed(1) + " MeV, energy released " + (M - m1 - m2).toFixed(1) + " MeV";
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
var mp = 0.9383;
var padL = 46, padR = 16, padT = 20, padB = 34;
var x0 = padL, x1 = W - padR, y0 = H - padB, y1 = padT;
var lxmin = 0, lxmax = 4;
var lymin = 0, lymax = 4.4;
var X = function (lx) { return x0 + (lx - lxmin) / (lxmax - lxmin) * (x1 - x0); };
var Y = function (ly) { return y0 + (ly - lymin) / (lymax - lymin) * (y1 - y0); };

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(x0, y1); ctx.lineTo(x0, y0); ctx.lineTo(x1, y0);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
var labx = ["1 GeV", "10", "100", "1 TeV", "10 TeV"];
var i;
for (i = 0; i <= 4; i++) {
  ctx.beginPath();
  ctx.moveTo(X(i), y0); ctx.lineTo(X(i), y0 + 4);
  ctx.strokeStyle = C.rule;
  ctx.stroke();
  ctx.fillText(labx[i], X(i), y0 + 14);
}
ctx.textAlign = "right";
var laby = ["1", "10", "100", "1000", "10000"];
for (i = 0; i <= 4; i++) {
  ctx.beginPath();
  ctx.moveTo(x0 - 4, Y(i)); ctx.lineTo(x0, Y(i));
  ctx.strokeStyle = C.rule;
  ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(laby[i], x0 - 7, Y(i));
}
ctx.textAlign = "left";
ctx.fillStyle = C.figure;
ctx.fillText("root-s in GeV", x0 - 40, padT - 10);
ctx.textAlign = "right";
ctx.fillText("beam energy", x1, y0 + 26);

var lx, E, v;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (lx = lxmin; lx <= lxmax + 1e-9; lx += 0.05) {
  E = Math.pow(10, lx);
  v = Math.log(2 * E) / Math.LN10;
  if (lx === lxmin) ctx.moveTo(X(lx), Y(v)); else ctx.lineTo(X(lx), Y(v));
}
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.beginPath();
for (lx = lxmin; lx <= lxmax + 1e-9; lx += 0.05) {
  E = Math.pow(10, lx);
  v = Math.log(Math.sqrt(2 * mp * mp + 2 * mp * E)) / Math.LN10;
  if (lx === lxmin) ctx.moveTo(X(lx), Y(v)); else ctx.lineTo(X(lx), Y(v));
}
ctx.stroke();

var Ec = p.beam;
var lxc = Math.log(Ec) / Math.LN10;
var col = 2 * Ec;
var fix = Math.sqrt(2 * mp * mp + 2 * mp * Ec);
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(X(lxc), y0); ctx.lineTo(X(lxc), Y(Math.log(col) / Math.LN10));
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(X(lxc), Y(Math.log(col) / Math.LN10), 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(X(lxc), Y(Math.log(fix) / Math.LN10), 5, 0, Math.PI * 2);
ctx.fill();

ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("collider, two beams head-on", X(0.15), Y(3.9));
ctx.fillStyle = C.figure;
ctx.fillText("fixed target, stationary proton", X(0.15), Y(3.55));

out.note = "beam " + (Ec >= 1000 ? (Ec / 1000).toFixed(2) + " TeV" : Ec.toFixed(0) + " GeV") + ": collider root-s = " + col.toFixed(0) + " GeV, fixed target root-s = " + fix.toFixed(1) + " GeV";
